/* English Quest: carefully curated learning dataset, 2026. Stable question IDs. */
window.EQ_DATA={"version":1,"units":[{"id":"a2-01","level":"A2","tag":"Daily","title":"Daily routines","goal":"毎日の行動を自然に説明する","rule":"現在形、頻度を表す副詞、三単現を整理する。","examples":["I usually leave at eight. = 普段8時に出発する。","She never skips breakfast. = 彼女は朝食を抜かない。"],"questions":[{"id":"a2-01-q01","stem":"My sister ___ to school by bus every day.","correct":"goes","options":["goes","go","going","gone"],"jp":"姉は毎日バスで通学する。","why":"主語が三人称単数の現在形なので goes。","level":"A2","unit":"a2-01"},{"id":"a2-01-q02","stem":"I ___ drink coffee after 6 p.m. because I cannot sleep.","correct":"never","options":["never","already","yet","ago"],"jp":"眠れなくなるので夕方6時以降コーヒーを飲まない。","why":"習慣の否定を表す頻度副詞は never。","level":"A2","unit":"a2-01"},{"id":"a2-01-q03","stem":"___ often do you practise English?","correct":"How","options":["How","What","Where","Which"],"jp":"どのくらい頻繁に英語を練習する？","why":"頻度を尋ねるのは How often。","level":"A2","unit":"a2-01"},{"id":"a2-01-q04","stem":"He doesn't ___ television before school.","correct":"watch","options":["watch","watches","watched","watching"],"jp":"彼は登校前にテレビを見ない。","why":"doesn't の後は動詞の原形。","level":"A2","unit":"a2-01"},{"id":"a2-01-q05","stem":"I'm usually at home ___ Sundays.","correct":"on","options":["on","at","in","to"],"jp":"日曜日はたいてい家にいる。","why":"曜日には on を使う。","level":"A2","unit":"a2-01"},{"id":"a2-01-q06","stem":"It takes me twenty minutes ___ to school.","correct":"to walk","options":["to walk","walk","walking","walked"],"jp":"学校まで歩いて20分かかる。","why":"It takes + 人 + 時間 + to do。","level":"A2","unit":"a2-01"},{"id":"a2-01-q07","stem":"We ___ have dinner at seven, but today we're eating late.","correct":"usually","options":["usually","yesterday","soon","now"],"jp":"普段は7時に夕食だが、今日は遅い。","why":"現在の例外と対比する習慣なので usually。","level":"A2","unit":"a2-01"},{"id":"a2-01-q08","stem":"My parents ___ work on Saturdays.","correct":"don't","options":["don't","doesn't","isn't","aren't"],"jp":"両親は土曜日に働かない。","why":"複数主語の一般動詞否定は don't。","level":"A2","unit":"a2-01"}]},{"id":"a2-02","level":"A2","tag":"Past","title":"Past experiences","goal":"過去の出来事を時系列で話す","rule":"過去形・不規則動詞・過去進行形の基礎。","examples":["I went there last week. = 先週そこに行った。","I was reading when she called. = 彼女から電話が来た時、読書していた。"],"questions":[{"id":"a2-02-q01","stem":"We ___ to the museum yesterday.","correct":"went","options":["went","go","gone","going"],"jp":"昨日博物館に行った。","why":"yesterday で過去形 went。","level":"A2","unit":"a2-02"},{"id":"a2-02-q02","stem":"I ___ my keys on the train last night.","correct":"lost","options":["lost","lose","losing","loss"],"jp":"昨夜電車に鍵を忘れた。","why":"lose の過去形は lost。","level":"A2","unit":"a2-02"},{"id":"a2-02-q03","stem":"While I ___ dinner, my friend called.","correct":"was cooking","options":["was cooking","cook","am cooking","have cooked"],"jp":"夕食を作っている最中に友人から電話が来た。","why":"過去の進行中動作には was cooking。","level":"A2","unit":"a2-02"},{"id":"a2-02-q04","stem":"She ___ not visit her grandparents last weekend.","correct":"did","options":["did","does","was","has"],"jp":"先週末、祖父母に会いに行かなかった。","why":"過去の一般動詞の否定は did not。","level":"A2","unit":"a2-02"},{"id":"a2-02-q05","stem":"What time ___ the film start yesterday?","correct":"did","options":["did","does","was","has"],"jp":"昨日その映画は何時に始まった？","why":"過去の疑問文は did + 原形。","level":"A2","unit":"a2-02"},{"id":"a2-02-q06","stem":"I ___ a beautiful postcard from Kyoto.","correct":"bought","options":["bought","buyed","buy","buying"],"jp":"京都で美しい絵葉書を買った。","why":"buy の過去形は bought。","level":"A2","unit":"a2-02"},{"id":"a2-02-q07","stem":"They were playing tennis when it ___ to rain.","correct":"started","options":["started","starting","starts","has started"],"jp":"テニス中に雨が降り出した。","why":"進行中の出来事を中断する動作は過去形。","level":"A2","unit":"a2-02"},{"id":"a2-02-q08","stem":"I didn't ___ the answer at first.","correct":"know","options":["know","knew","known","knowing"],"jp":"最初は答えが分からなかった。","why":"didn't の後は know。","level":"A2","unit":"a2-02"}]},{"id":"a2-03","level":"A2","tag":"Future","title":"Plans and invitations","goal":"予定・提案・約束ができる","rule":"be going to と will、丁寧な誘い方。","examples":["I'm going to study tonight. = 今夜勉強する予定。","Would you like to join us? = 一緒に来ませんか。"],"questions":[{"id":"a2-03-q01","stem":"Look at those dark clouds! It ___ rain.","correct":"is going to","options":["is going to","will have","was","has"],"jp":"黒い雲を見て。雨が降りそう。","why":"現在の根拠からの予測には be going to。","level":"A2","unit":"a2-03"},{"id":"a2-03-q02","stem":"I think the exam ___ be difficult.","correct":"will","options":["will","is","was going","has"],"jp":"試験は難しいと思う。","why":"予測を表す I think ... will。","level":"A2","unit":"a2-03"},{"id":"a2-03-q03","stem":"___ you like to come with us?","correct":"Would","options":["Would","Do","Are","Have"],"jp":"一緒に来ませんか。","why":"丁寧な誘いは Would you like to ...?","level":"A2","unit":"a2-03"},{"id":"a2-03-q04","stem":"We're meeting at six, ___ we?","correct":"aren't","options":["aren't","don't","haven't","won't"],"jp":"6時に待ち合わせだよね。","why":"We're meeting の付加疑問は aren't we。","level":"A2","unit":"a2-03"},{"id":"a2-03-q05","stem":"I ___ help you with your bag.","correct":"will","options":["will","have","am going","did"],"jp":"かばんを持つよ。","why":"その場で申し出る意志は will。","level":"A2","unit":"a2-03"},{"id":"a2-03-q06","stem":"Let's ___ a break after this exercise.","correct":"take","options":["take","taking","took","taken"],"jp":"この演習の後で休憩しよう。","why":"Let's の後は動詞原形。","level":"A2","unit":"a2-03"},{"id":"a2-03-q07","stem":"Are you free ___ Friday evening?","correct":"on","options":["on","in","at","by"],"jp":"金曜の夜は空いている？","why":"曜日付きの夕方は on Friday evening。","level":"A2","unit":"a2-03"},{"id":"a2-03-q08","stem":"I'm looking forward to ___ you next week.","correct":"seeing","options":["seeing","see","saw","seen"],"jp":"来週会えるのを楽しみにしている。","why":"look forward to の to は前置詞で動名詞。","level":"A2","unit":"a2-03"}]},{"id":"a2-04","level":"A2","tag":"Travel","title":"Travel and directions","goal":"移動・交通・道案内ができる","rule":"前置詞とよく使う旅行の定型表現。","examples":["How do I get to the station? = 駅にはどう行きますか。","Could I have a return ticket? = 往復切符をください。"],"questions":[{"id":"a2-04-q01","stem":"Excuse me, how do I get ___ the station?","correct":"to","options":["to","at","in","with"],"jp":"駅への行き方を教えてください。","why":"目的地へ向かう get to。","level":"A2","unit":"a2-04"},{"id":"a2-04-q02","stem":"Turn left ___ the traffic lights.","correct":"at","options":["at","on","by","in"],"jp":"信号で左に曲がって。","why":"特定地点で曲がる場合 at。","level":"A2","unit":"a2-04"},{"id":"a2-04-q03","stem":"I'd like a ___ ticket to London and back.","correct":"return","options":["return","single","one-way","daily"],"jp":"ロンドンまでの往復切符が欲しい。","why":"and back は往復の意味。return ticket。","level":"A2","unit":"a2-04"},{"id":"a2-04-q04","stem":"The train leaves ___ platform three.","correct":"from","options":["from","of","into","by"],"jp":"電車は3番ホームから出ます。","why":"出発地点は from。","level":"A2","unit":"a2-04"},{"id":"a2-04-q05","stem":"Is this seat ___?","correct":"available","options":["available","possible","freezing","ability"],"jp":"この席は空いていますか。","why":"席の空きを尋ねる available。","level":"A2","unit":"a2-04"},{"id":"a2-04-q06","stem":"We arrived ___ Paris late at night.","correct":"in","options":["in","at","to","on"],"jp":"夜遅くパリに到着した。","why":"都市や国に着く場合 arrive in。","level":"A2","unit":"a2-04"},{"id":"a2-04-q07","stem":"You need to ___ the bus at the next stop.","correct":"get off","options":["get off","get up","get in","get over"],"jp":"次の停留所でバスを降りる必要がある。","why":"get off a bus が正しい。","level":"A2","unit":"a2-04"},{"id":"a2-04-q08","stem":"Could you tell me where the nearest pharmacy ___?","correct":"is","options":["is","are","does","has"],"jp":"一番近い薬局がどこか教えていただけますか。","why":"間接疑問文は where + 主語 + 動詞。","level":"A2","unit":"a2-04"}]},{"id":"a2-05","level":"A2","tag":"People","title":"People and comparisons","goal":"人物描写・比較・感想ができる","rule":"比較級・最上級・形容詞の用法。","examples":["This one is cheaper. = こちらの方が安い。","She is the most patient person I know. = 私が知る中で最も忍耐強い人。"],"questions":[{"id":"a2-05-q01","stem":"This book is ___ than the one I read before.","correct":"more interesting","options":["more interesting","interestinger","most interesting","interesting"],"jp":"この本は前に読んだものより面白い。","why":"長めの形容詞の比較級は more interesting。","level":"A2","unit":"a2-05"},{"id":"a2-05-q02","stem":"My brother is two years ___ than me.","correct":"older","options":["older","oldest","more old","old"],"jp":"兄は私より2歳年上。","why":"than とともに比較級 older。","level":"A2","unit":"a2-05"},{"id":"a2-05-q03","stem":"Which is the ___ building in your town?","correct":"tallest","options":["tallest","taller","most tall","tall"],"jp":"町で一番高い建物はどれ？","why":"the + 最上級 tallest。","level":"A2","unit":"a2-05"},{"id":"a2-05-q04","stem":"She speaks English ___ than I do.","correct":"more fluently","options":["more fluently","fluenter","most fluently","fluent"],"jp":"彼女は私より流暢に英語を話す。","why":"動詞を修飾する副詞の比較級。","level":"A2","unit":"a2-05"},{"id":"a2-05-q05","stem":"He's good ___ explaining difficult ideas.","correct":"at","options":["at","in","to","on"],"jp":"彼は難しい考えを説明するのが得意。","why":"be good at + 動名詞。","level":"A2","unit":"a2-05"},{"id":"a2-05-q06","stem":"The film was ___ than I expected.","correct":"better","options":["better","gooder","best","well"],"jp":"映画は思ったより良かった。","why":"good の比較級は better。","level":"A2","unit":"a2-05"},{"id":"a2-05-q07","stem":"These shoes are not as expensive ___ those.","correct":"as","options":["as","than","like","from"],"jp":"この靴はあの靴ほど高くない。","why":"not as ... as の組み合わせ。","level":"A2","unit":"a2-05"},{"id":"a2-05-q08","stem":"She's one of the ___ students in our class.","correct":"kindest","options":["kindest","kinder","most kindest","more kind"],"jp":"彼女はクラスで最も優しい生徒の一人。","why":"one of the + 最上級 + 複数名詞。","level":"A2","unit":"a2-05"}]},{"id":"a2-06","level":"A2","tag":"Social","title":"Everyday conversation","goal":"頼む・謝る・説明する","rule":"不定詞、丁寧な依頼、会話の受け答え。","examples":["Could you repeat that, please? = もう一度言ってください。","I'm sorry for being late. = 遅れてごめんなさい。"],"questions":[{"id":"a2-06-q01","stem":"Could you ___ that a little more slowly?","correct":"say","options":["say","telling","said","says"],"jp":"もう少しゆっくり言ってもらえますか。","why":"Could you + 動詞原形。","level":"A2","unit":"a2-06"},{"id":"a2-06-q02","stem":"I'm sorry ___ being late.","correct":"for","options":["for","to","of","at"],"jp":"遅れてすみません。","why":"sorry for + 動名詞。","level":"A2","unit":"a2-06"},{"id":"a2-06-q03","stem":"Would you mind ___ the window?","correct":"opening","options":["opening","open","to open","opened"],"jp":"窓を開けてもらえませんか。","why":"mind の後は動名詞。","level":"A2","unit":"a2-06"},{"id":"a2-06-q04","stem":"I don't understand. What does this word ___?","correct":"mean","options":["mean","means","meaning","meant"],"jp":"分からない。この単語はどういう意味？","why":"does の後は原形 mean。","level":"A2","unit":"a2-06"},{"id":"a2-06-q05","stem":"Can I ___ your pen for a moment?","correct":"borrow","options":["borrow","lend","give","offer"],"jp":"少しペンを借りてもいい？","why":"borrow は借りる、lend は貸す。","level":"A2","unit":"a2-06"},{"id":"a2-06-q06","stem":"You look tired. You ___ take a rest.","correct":"should","options":["should","mustn't","don't need","might to"],"jp":"疲れて見える。休んだ方がいい。","why":"やわらかい助言は should。","level":"A2","unit":"a2-06"},{"id":"a2-06-q07","stem":"Thank you for your help. — You're ___.","correct":"welcome","options":["welcome","welcomed","welcoming","well"],"jp":"手伝ってくれてありがとう。どういたしまして。","why":"定型表現 You're welcome。","level":"A2","unit":"a2-06"},{"id":"a2-06-q08","stem":"I have trouble ___ the difference between these sounds.","correct":"hearing","options":["hearing","hear","to hear","heard"],"jp":"この音の違いを聞き取るのが難しい。","why":"have trouble + 動名詞。","level":"A2","unit":"a2-06"}]},{"id":"b1-01","level":"B1","tag":"Perfect","title":"Experiences and change","goal":"経験や継続を説明する","rule":"現在完了と過去形の使い分け。","examples":["I've lived here for three years. = ここに3年住んでいる。","I saw her yesterday. = 昨日彼女に会った。"],"questions":[{"id":"b1-01-q01","stem":"I've lived in this city ___ 2022.","correct":"since","options":["since","for","during","ago"],"jp":"2022年からこの街に住んでいる。","why":"起点には since。","level":"B1","unit":"b1-01"},{"id":"b1-01-q02","stem":"We have known each other ___ five years.","correct":"for","options":["for","since","during","from"],"jp":"5年間知り合いだ。","why":"期間には for。","level":"B1","unit":"b1-01"},{"id":"b1-01-q03","stem":"Have you ___ tried Korean food?","correct":"ever","options":["ever","never","yet","ago"],"jp":"韓国料理を食べたことはありますか。","why":"経験を尋ねる ever。","level":"B1","unit":"b1-01"},{"id":"b1-01-q04","stem":"She hasn't finished the report ___.","correct":"yet","options":["yet","already","still now","ever"],"jp":"彼女はまだレポートを終えていない。","why":"否定文の文末で yet。","level":"B1","unit":"b1-01"},{"id":"b1-01-q05","stem":"I ___ that film two days ago.","correct":"watched","options":["watched","have watched","watch","had watching"],"jp":"2日前にその映画を観た。","why":"two days ago は過去形。","level":"B1","unit":"b1-01"},{"id":"b1-01-q06","stem":"He's ___ left, so you just missed him.","correct":"just","options":["just","yet","ever","ago"],"jp":"彼はちょうど出たところ。","why":"現在完了で just は直前の完了。","level":"B1","unit":"b1-01"},{"id":"b1-01-q07","stem":"This is the best book I've ___ read.","correct":"ever","options":["ever","never","yet","since"],"jp":"これまで読んだ中で最高の本だ。","why":"最上級と現在完了の経験を強調する ever。","level":"B1","unit":"b1-01"},{"id":"b1-01-q08","stem":"I've ___ my wallet, so I can't pay.","correct":"lost","options":["lost","lose","losing","loses"],"jp":"財布をなくしたから支払えない。","why":"現在の結果に関わる現在完了 have lost。","level":"B1","unit":"b1-01"}]},{"id":"b1-02","level":"B1","tag":"Condition","title":"Conditions and consequences","goal":"条件・仮定・助言を伝える","rule":"first/second conditional、unless。","examples":["If it rains, we'll stay home. = 雨なら家にいる。","If I were you, I'd ask. = 私なら尋ねる。"],"questions":[{"id":"b1-02-q01","stem":"If it rains tomorrow, we ___ at home.","correct":"will stay","options":["will stay","would stay","stayed","staying"],"jp":"明日雨なら家にいるだろう。","why":"現実的な未来の条件 If + 現在、will + 原形。","level":"B1","unit":"b1-02"},{"id":"b1-02-q02","stem":"If I ___ more time, I would learn Italian.","correct":"had","options":["had","have","will have","having"],"jp":"もっと時間があればイタリア語を学ぶのに。","why":"仮定法過去 If + 過去形。","level":"B1","unit":"b1-02"},{"id":"b1-02-q03","stem":"You won't pass ___ you study regularly.","correct":"unless","options":["unless","because","although","while"],"jp":"定期的に勉強しないと合格しない。","why":"unless は if ... not。","level":"B1","unit":"b1-02"},{"id":"b1-02-q04","stem":"If I were you, I ___ apologise.","correct":"would","options":["would","will","can","am"],"jp":"私なら謝ると思う。","why":"If I were you, I would。","level":"B1","unit":"b1-02"},{"id":"b1-02-q05","stem":"We'll go hiking if the weather ___ good.","correct":"is","options":["is","will be","was","would be"],"jp":"天気が良ければハイキングする。","why":"条件節では未来でも現在形。","level":"B1","unit":"b1-02"},{"id":"b1-02-q06","stem":"You can borrow the bike ___ you bring it back tonight.","correct":"as long as","options":["as long as","despite","whereas","even though"],"jp":"今夜返すなら自転車を借りていい。","why":"as long as は条件付きの許可。","level":"B1","unit":"b1-02"},{"id":"b1-02-q07","stem":"If she studied harder, she ___ improve quickly.","correct":"would","options":["would","will","has","is"],"jp":"もっと勉強すれば早く上達するのに。","why":"非現実の仮定には would。","level":"B1","unit":"b1-02"},{"id":"b1-02-q08","stem":"Call me ___ you arrive at the station.","correct":"when","options":["when","unless","despite","because of"],"jp":"駅に着いたら電話して。","why":"時を表す節も現在形で未来を表せる。","level":"B1","unit":"b1-02"}]},{"id":"b1-03","level":"B1","tag":"Narrative","title":"Tell a clear story","goal":"出来事の前後関係を伝える","rule":"過去完了・時間接続詞・関係節。","examples":["By the time I arrived, the train had left. = 着いた時、電車は出た後だった。","While we were waiting, it began to snow. = 待っている間に雪が降り始めた。"],"questions":[{"id":"b1-03-q01","stem":"When I got there, the concert ___ already started.","correct":"had","options":["had","has","was","is"],"jp":"着いた時にはコンサートはもう始まっていた。","why":"過去の基準時より前は had + 過去分詞。","level":"B1","unit":"b1-03"},{"id":"b1-03-q02","stem":"I couldn't open the door because I ___ my keys.","correct":"had forgotten","options":["had forgotten","have forgotten","forget","am forgetting"],"jp":"鍵を忘れたのでドアを開けられなかった。","why":"鍵を忘れたのが開けられない時より前。","level":"B1","unit":"b1-03"},{"id":"b1-03-q03","stem":"___ I was walking home, I saw an old friend.","correct":"While","options":["While","Unless","Despite","Although of"],"jp":"帰宅中に旧友を見かけた。","why":"進行中の動作には While。","level":"B1","unit":"b1-03"},{"id":"b1-03-q04","stem":"The woman ___ helped us was very kind.","correct":"who","options":["who","which","where","whose"],"jp":"助けてくれた女性は親切だった。","why":"人を主語として説明する関係代名詞 who。","level":"B1","unit":"b1-03"},{"id":"b1-03-q05","stem":"That's the café ___ we first met.","correct":"where","options":["where","who","which","whose"],"jp":"そこは初めて会ったカフェだ。","why":"場所を表す関係副詞 where。","level":"B1","unit":"b1-03"},{"id":"b1-03-q06","stem":"I was exhausted because I ___ working all day.","correct":"had been","options":["had been","have been","was been","will be"],"jp":"一日中働き続けて疲れ切っていた。","why":"過去まで続いた動作の継続は過去完了進行形。","level":"B1","unit":"b1-03"},{"id":"b1-03-q07","stem":"He told me that he ___ moving to Canada.","correct":"was","options":["was","is","has","will"],"jp":"彼はカナダに引っ越す予定だと話した。","why":"過去の発言に合わせた時制の一致。","level":"B1","unit":"b1-03"},{"id":"b1-03-q08","stem":"I finally found the book ___ I'd been looking for.","correct":"that","options":["that","where","who","whose"],"jp":"探していた本をやっと見つけた。","why":"物を目的語として説明する関係代名詞 that。","level":"B1","unit":"b1-03"}]},{"id":"b1-04","level":"B1","tag":"Opinion","title":"Express an opinion","goal":"理由を示し反論を受け止める","rule":"however、although、because、in my view。","examples":["In my view, public transport should be cheaper. = 私は公共交通はもっと安くすべきだと思う。","Although it costs more, it lasts longer. = 高いが長持ちする。"],"questions":[{"id":"b1-04-q01","stem":"___ I understand your point, I disagree with your conclusion.","correct":"Although","options":["Although","Because","Despite of","Unless"],"jp":"言いたいことは分かるが、結論には反対だ。","why":"Although + 主語 + 動詞。","level":"B1","unit":"b1-04"},{"id":"b1-04-q02","stem":"The product is useful. ___, it is too expensive.","correct":"However","options":["However","Because","Therefore of","Despite"],"jp":"商品は便利だ。しかし高すぎる。","why":"文を逆接でつなぐ However。","level":"B1","unit":"b1-04"},{"id":"b1-04-q03","stem":"In my ___, schools should teach practical skills.","correct":"opinion","options":["opinion","think","believe","mindset of"],"jp":"私の考えでは学校は実用技能を教えるべきだ。","why":"In my opinion が定型。","level":"B1","unit":"b1-04"},{"id":"b1-04-q04","stem":"One advantage ___ studying abroad is meeting new people.","correct":"of","options":["of","to","for","by"],"jp":"留学の利点は人に出会えること。","why":"advantage of + 動名詞。","level":"B1","unit":"b1-04"},{"id":"b1-04-q05","stem":"I agree with you ___ some extent.","correct":"to","options":["to","at","in","for"],"jp":"ある程度は賛成だ。","why":"to some extent は程度を限定する。","level":"B1","unit":"b1-04"},{"id":"b1-04-q06","stem":"We should recycle more, ___ it helps reduce waste.","correct":"because","options":["because","however","despite","unless"],"jp":"ごみを減らせるので、もっとリサイクルすべき。","why":"原因を示す because。","level":"B1","unit":"b1-04"},{"id":"b1-04-q07","stem":"___ the high price, the laptop sold well.","correct":"Despite","options":["Despite","Although","Even","Because"],"jp":"高価にもかかわらずよく売れた。","why":"Despite の後は名詞句。","level":"B1","unit":"b1-04"},{"id":"b1-04-q08","stem":"I see what you ___, but there is another issue.","correct":"mean","options":["mean","meaning","meant to","thought to"],"jp":"言いたいことは分かるが別の問題がある。","why":"会話定型 I see what you mean。","level":"B1","unit":"b1-04"}]},{"id":"b1-05","level":"B1","tag":"Study","title":"School, work and goals","goal":"学業・目標・仕事の説明","rule":"目的・努力・面接で使える表現。","examples":["I'm responsible for organising the event. = イベントの運営を担当している。","I need to improve my time management. = 時間管理を改善したい。"],"questions":[{"id":"b1-05-q01","stem":"I'm responsible ___ organising the meeting.","correct":"for","options":["for","of","to","at"],"jp":"会議の準備を担当している。","why":"be responsible for + 動名詞。","level":"B1","unit":"b1-05"},{"id":"b1-05-q02","stem":"I decided ___ a coding course this year.","correct":"to take","options":["to take","taking","take","took"],"jp":"今年プログラミング講座を受けると決めた。","why":"decide to + 原形。","level":"B1","unit":"b1-05"},{"id":"b1-05-q03","stem":"We need to ___ a deadline for the project.","correct":"meet","options":["meet","do","make up","reach to"],"jp":"プロジェクトの締切に間に合わせる必要がある。","why":"meet a deadline は決まり文句。","level":"B1","unit":"b1-05"},{"id":"b1-05-q04","stem":"She is interested ___ environmental science.","correct":"in","options":["in","on","at","for"],"jp":"彼女は環境科学に興味がある。","why":"interested in。","level":"B1","unit":"b1-05"},{"id":"b1-05-q05","stem":"I look forward to ___ from you soon.","correct":"hearing","options":["hearing","hear","heard","be heard"],"jp":"お返事を楽しみにしています。","why":"look forward to + 動名詞。","level":"B1","unit":"b1-05"},{"id":"b1-05-q06","stem":"Could you give me some ___ on my presentation?","correct":"feedback","options":["feedback","feedbacks","advices","inform"],"jp":"発表へのフィードバックをもらえますか。","why":"feedback は不可算名詞。","level":"B1","unit":"b1-05"},{"id":"b1-05-q07","stem":"I want to gain more practical ___.","correct":"experience","options":["experience","experiences of work","experiment","experienced"],"jp":"実務経験をもっと積みたい。","why":"一般的な実務経験は不可算 experience。","level":"B1","unit":"b1-05"},{"id":"b1-05-q08","stem":"He succeeded ___ passing the entrance exam.","correct":"in","options":["in","to","on","for"],"jp":"彼は入学試験に合格することに成功した。","why":"succeed in + 動名詞。","level":"B1","unit":"b1-05"}]},{"id":"b1-06","level":"B1","tag":"Everyday","title":"Real-life problem solving","goal":"トラブルに対応し意図を明確にする","rule":"丁寧な交渉、確認、苦情、電話表現。","examples":["I'm afraid there's been a mistake. = 恐れ入りますが間違いがあったようです。","Would it be possible to change the date? = 日付の変更は可能ですか。"],"questions":[{"id":"b1-06-q01","stem":"I'm afraid there's been a ___ with my order.","correct":"mistake","options":["mistake","mistaken","misunderstand","wrongly"],"jp":"注文に間違いがあったようです。","why":"There's been a mistake は丁寧な苦情の出だし。","level":"B1","unit":"b1-06"},{"id":"b1-06-q02","stem":"Would it be possible ___ the appointment?","correct":"to reschedule","options":["to reschedule","rescheduling","reschedule","rescheduled"],"jp":"予定を変更できるでしょうか。","why":"possible to + 原形。","level":"B1","unit":"b1-06"},{"id":"b1-06-q03","stem":"Could you ___ what you mean by that?","correct":"clarify","options":["clarify","clear","clarity","clearly"],"jp":"どういう意味か説明してもらえますか。","why":"clarify は動詞。","level":"B1","unit":"b1-06"},{"id":"b1-06-q04","stem":"I'm calling ___ my booking for tomorrow.","correct":"about","options":["about","of","by","from"],"jp":"明日の予約について電話しています。","why":"call about は用件を示す。","level":"B1","unit":"b1-06"},{"id":"b1-06-q05","stem":"I was wondering ___ you could help me.","correct":"if","options":["if","that","why","what"],"jp":"手伝ってもらえるかと思いまして。","why":"丁寧な間接依頼は I was wondering if。","level":"B1","unit":"b1-06"},{"id":"b1-06-q06","stem":"Could I speak to the person in ___, please?","correct":"charge","options":["charge","control of","charged","responsible of"],"jp":"担当者と話せますか。","why":"the person in charge は担当者。","level":"B1","unit":"b1-06"},{"id":"b1-06-q07","stem":"I can't make it tonight. Can we ___ another day?","correct":"arrange","options":["arrange","manage","create up","make for"],"jp":"今夜は行けない。別の日にできる？","why":"arrange another day と表現できる。","level":"B1","unit":"b1-06"},{"id":"b1-06-q08","stem":"Thank you for bringing this ___ our attention.","correct":"to","options":["to","at","of","on"],"jp":"この件をご指摘いただきありがとうございます。","why":"bring something to someone's attention。","level":"B1","unit":"b1-06"}]},{"id":"b2-01","level":"B2","tag":"Precision","title":"Advanced tenses and aspect","goal":"正確な時間関係・経験を表す","rule":"未来完了・継続・過去の推量。","examples":["By Friday, I'll have finished it. = 金曜までに終えているだろう。","She must have forgotten. = 忘れたに違いない。"],"questions":[{"id":"b2-01-q01","stem":"By next June, I ___ completed my internship.","correct":"will have","options":["will have","would have","had","have been"],"jp":"来年6月までにはインターンを終えているだろう。","why":"未来の基準時までの完了は will have + 過去分詞。","level":"B2","unit":"b2-01"},{"id":"b2-01-q02","stem":"She ___ been studying for hours before the exam began.","correct":"had","options":["had","has","was","will"],"jp":"試験開始前、彼女は何時間も勉強していた。","why":"過去の基準点までの継続は had been -ing。","level":"B2","unit":"b2-01"},{"id":"b2-01-q03","stem":"He isn't here. He ___ have missed the train.","correct":"might","options":["might","should to","had to","can to"],"jp":"彼がいない。電車に乗り遅れたのかもしれない。","why":"過去の可能性は might have + 過去分詞。","level":"B2","unit":"b2-01"},{"id":"b2-01-q04","stem":"You ___ have told me sooner; I could have helped.","correct":"should","options":["should","must to","might to","would to"],"jp":"もっと早く教えてくれれば手伝えたのに。","why":"過去への後悔や非難は should have + 過去分詞。","level":"B2","unit":"b2-01"},{"id":"b2-01-q05","stem":"I wish I ___ studied harder for that exam.","correct":"had","options":["had","have","would","was"],"jp":"あの試験でもっと勉強していればよかった。","why":"過去への後悔は wish + 過去完了。","level":"B2","unit":"b2-01"},{"id":"b2-01-q06","stem":"She is believed ___ the country last month.","correct":"to have left","options":["to have left","to leave","leaving","left"],"jp":"彼女は先月出国したと考えられている。","why":"be believed to have + 過去分詞 は先行する出来事。","level":"B2","unit":"b2-01"},{"id":"b2-01-q07","stem":"I ___ rather you didn't mention my name.","correct":"would","options":["would","had","should","must"],"jp":"私の名前は出さないでほしい。","why":"would rather + 人 + 過去形で現在の希望。","level":"B2","unit":"b2-01"},{"id":"b2-01-q08","stem":"By the time you arrive, we ___ waiting for two hours.","correct":"will have been","options":["will have been","will have","have been","had been"],"jp":"君が着く頃には2時間待ったことになる。","why":"未来完了進行形 will have been -ing。","level":"B2","unit":"b2-01"}]},{"id":"b2-02","level":"B2","tag":"Hypothesis","title":"Hypothetical reasoning","goal":"反事実を検討する","rule":"mixed conditional、if only、without。","examples":["If I'd left earlier, I wouldn't be late now. = もっと早く出ていれば今遅刻していない。","Without your help, I'd have failed. = 君の助けがなければ失敗していた。"],"questions":[{"id":"b2-02-q01","stem":"If I had taken the offer, I ___ living in Berlin now.","correct":"would be","options":["would be","will be","had been","am being"],"jp":"あの提案を受けていれば今ベルリンに住んでいるだろう。","why":"過去の条件と現在の結果の混合仮定法。","level":"B2","unit":"b2-02"},{"id":"b2-02-q02","stem":"If only I ___ about the cancellation earlier!","correct":"had known","options":["had known","know","will know","have know"],"jp":"中止をもっと早く知っていれば！","why":"過去への後悔は If only + 過去完了。","level":"B2","unit":"b2-02"},{"id":"b2-02-q03","stem":"___ your advice, I would have made a costly mistake.","correct":"Without","options":["Without","Unless","Whereas","Although"],"jp":"君の助言がなければ高い代償の失敗をしただろう。","why":"Without + 名詞句 は仮定の条件。","level":"B2","unit":"b2-02"},{"id":"b2-02-q04","stem":"Had she known the truth, she ___ have reacted differently.","correct":"would","options":["would","will","did","has"],"jp":"真実を知っていたら、反応が違っただろう。","why":"倒置 Had she known = If she had known。","level":"B2","unit":"b2-02"},{"id":"b2-02-q05","stem":"Suppose you ___ offered a scholarship. What would you do?","correct":"were","options":["were","are","have","will"],"jp":"奨学金を提案されたらどうする？","why":"仮定の問いには were offered。","level":"B2","unit":"b2-02"},{"id":"b2-02-q06","stem":"I'd sooner ___ the problem directly than ignore it.","correct":"address","options":["address","addressing","to address","addressed"],"jp":"問題を無視するより直接扱いたい。","why":"would sooner + 動詞原形。","level":"B2","unit":"b2-02"},{"id":"b2-02-q07","stem":"But for the delay, we ___ arrived on time.","correct":"would have","options":["would have","will have","had","are"],"jp":"遅延がなければ時間通り着いていた。","why":"But for は without と同様に反事実の条件。","level":"B2","unit":"b2-02"},{"id":"b2-02-q08","stem":"If he were more organised, he ___ have forgotten the deadline yesterday.","correct":"wouldn't","options":["wouldn't","won't","didn't","hadn't"],"jp":"彼がもっときちんとしていれば昨日締切を忘れなかっただろう。","why":"現在の性質と過去の結果を結ぶ混合仮定法。","level":"B2","unit":"b2-02"}]},{"id":"b2-03","level":"B2","tag":"Argument","title":"Build a strong argument","goal":"証拠を根拠に議論する","rule":"対比・譲歩・因果関係を精密に述べる。","examples":["The evidence suggests that ... = 証拠は…を示唆する。","This does not necessarily mean that ... = これが必ずしも…を意味するわけではない。"],"questions":[{"id":"b2-03-q01","stem":"The data ___ that the policy had limited impact.","correct":"suggest","options":["suggest","insist","pretend","force"],"jp":"データは政策の効果が限定的だったことを示唆する。","why":"data suggest は断定を避けた学術的表現。","level":"B2","unit":"b2-03"},{"id":"b2-03-q02","stem":"This result does not ___ mean the method is ineffective.","correct":"necessarily","options":["necessarily","necessary","necessity","necessitate"],"jp":"この結果は必ずしも方法が無効という意味ではない。","why":"not necessarily は断定回避。","level":"B2","unit":"b2-03"},{"id":"b2-03-q03","stem":"One possible ___ is that participants were already motivated.","correct":"explanation","options":["explanation","explain","explication of","explanatory"],"jp":"一つの可能な説明は参加者が元々意欲的だったこと。","why":"名詞 explanation が必要。","level":"B2","unit":"b2-03"},{"id":"b2-03-q04","stem":"The benefits are substantial; ___, the costs cannot be ignored.","correct":"nevertheless","options":["nevertheless","therefore","likewise","as a result"],"jp":"利点は大きい。しかし費用も無視できない。","why":"対比・譲歩の nevertheless。","level":"B2","unit":"b2-03"},{"id":"b2-03-q05","stem":"It is important to distinguish correlation ___ causation.","correct":"from","options":["from","to","with","on"],"jp":"相関と因果関係を区別することが重要。","why":"distinguish A from B。","level":"B2","unit":"b2-03"},{"id":"b2-03-q06","stem":"The findings ___ the need for further investigation.","correct":"highlight","options":["highlight","refuse","doubt","deny of"],"jp":"調査結果は追加調査の必要性を浮き彫りにする。","why":"highlight the need for が自然。","level":"B2","unit":"b2-03"},{"id":"b2-03-q07","stem":"A key limitation of the study ___ its small sample size.","correct":"is","options":["is","are","being","have"],"jp":"研究の大きな限界は標本が小さいこと。","why":"主語 A key limitation は単数。","level":"B2","unit":"b2-03"},{"id":"b2-03-q08","stem":"The argument relies ___ an assumption that may be false.","correct":"on","options":["on","in","at","by"],"jp":"議論は誤りかもしれない前提に依拠する。","why":"rely on an assumption。","level":"B2","unit":"b2-03"}]},{"id":"b2-04","level":"B2","tag":"Collocation","title":"Natural collocations","goal":"英語らしい語の組み合わせを使う","rule":"直訳では不自然になりやすい定型コロケーション。","examples":["raise awareness = 意識を高める。","reach a compromise = 妥協点に達する。"],"questions":[{"id":"b2-04-q01","stem":"We need to ___ awareness of online privacy.","correct":"raise","options":["raise","lift","grow up","climb"],"jp":"オンラインのプライバシー意識を高めるべきだ。","why":"raise awareness。","level":"B2","unit":"b2-04"},{"id":"b2-04-q02","stem":"After an hour of discussion, they reached a ___.","correct":"compromise","options":["compromise","compromisation","midwaying","decisioning"],"jp":"1時間の協議の末、妥協点に達した。","why":"reach a compromise が定型。","level":"B2","unit":"b2-04"},{"id":"b2-04-q03","stem":"The company is taking ___ to reduce emissions.","correct":"steps","options":["steps","walks","stairs","paces"],"jp":"会社は排出削減に向けて措置を講じている。","why":"take steps to do。","level":"B2","unit":"b2-04"},{"id":"b2-04-q04","stem":"We must take the long-term effects into ___.","correct":"account","options":["account","count","consider","attention of"],"jp":"長期的影響を考慮しなければならない。","why":"take ... into account。","level":"B2","unit":"b2-04"},{"id":"b2-04-q05","stem":"The new app poses a serious ___ to user privacy.","correct":"threat","options":["threat","warning of","challenge against","dangerous"],"jp":"新しいアプリは利用者のプライバシーに重大な脅威となる。","why":"pose a threat to。","level":"B2","unit":"b2-04"},{"id":"b2-04-q06","stem":"He made a ___ effort to improve his pronunciation.","correct":"conscious","options":["conscious","conscience","consciously","conscientiousness"],"jp":"彼は発音改善に意識的に努力した。","why":"make a conscious effort。","level":"B2","unit":"b2-04"},{"id":"b2-04-q07","stem":"The two studies draw ___ different conclusions.","correct":"strikingly","options":["strikingly","striking","strike","struck"],"jp":"2つの研究は著しく異なる結論を出している。","why":"strikingly は different を修飾する副詞。","level":"B2","unit":"b2-04"},{"id":"b2-04-q08","stem":"We need to strike a ___ between speed and accuracy.","correct":"balance","options":["balance","middle","trade","weigh"],"jp":"速度と正確性のバランスを取る必要がある。","why":"strike a balance between A and B。","level":"B2","unit":"b2-04"}]},{"id":"b2-05","level":"B2","tag":"Media","title":"Media and critical thinking","goal":"情報を吟味し、信頼性を評価する","rule":"報道、偏り、情報源についての語彙。","examples":["The source seems credible. = 情報源は信頼できそうだ。","The headline is misleading. = 見出しは誤解を招く。"],"questions":[{"id":"b2-05-q01","stem":"The article makes a claim but provides no ___ to support it.","correct":"evidence","options":["evidence","evident","prove","proofs"],"jp":"記事は主張をしているが根拠がない。","why":"evidence は不可算名詞。","level":"B2","unit":"b2-05"},{"id":"b2-05-q02","stem":"The headline is ___ because it leaves out key facts.","correct":"misleading","options":["misleading","misled","mislead","misleadable"],"jp":"重要な事実を省いた見出しは誤解を招く。","why":"misleading は人を誤認させる性質。","level":"B2","unit":"b2-05"},{"id":"b2-05-q03","stem":"We should check whether the information comes from a ___ source.","correct":"reliable","options":["reliable","reliance","reliably","rely"],"jp":"信頼できる情報源か確認すべき。","why":"名詞 source を修飾する reliable。","level":"B2","unit":"b2-05"},{"id":"b2-05-q04","stem":"The report appears to be ___ towards one candidate.","correct":"biased","options":["biased","bias","biasing","biasly"],"jp":"その報告はある候補に偏っているようだ。","why":"be biased towards で偏向。","level":"B2","unit":"b2-05"},{"id":"b2-05-q05","stem":"Don't take the statistics at face ___.","correct":"value","options":["value","price","cost","worth"],"jp":"統計を額面どおり受け取らないで。","why":"at face value は疑わず受け入れること。","level":"B2","unit":"b2-05"},{"id":"b2-05-q06","stem":"A single example is not enough to ___ a general conclusion.","correct":"justify","options":["justify","justice","justification","justified"],"jp":"一例だけでは一般的結論の正当化には足りない。","why":"動詞 justify。","level":"B2","unit":"b2-05"},{"id":"b2-05-q07","stem":"This image was taken out of ___.","correct":"context","options":["context","content","contact","contract"],"jp":"この画像は文脈から切り離されていた。","why":"out of context。","level":"B2","unit":"b2-05"},{"id":"b2-05-q08","stem":"It's essential to ___ facts from opinions.","correct":"separate","options":["separate","division","distinction","split up with"],"jp":"事実と意見を区別するのが不可欠。","why":"separate A from B。","level":"B2","unit":"b2-05"}]},{"id":"b2-06","level":"B2","tag":"Interaction","title":"Diplomacy and discussion","goal":"反対意見に適切に応答する","rule":"提案、条件付き同意、議論の整理。","examples":["I take your point; however ... = その点は分かるが…。","Could you elaborate on that? = そこを詳しく説明できますか。"],"questions":[{"id":"b2-06-q01","stem":"Could you ___ on that point a little?","correct":"elaborate","options":["elaborate","elaboration","elaborately","laborate"],"jp":"その点を少し詳しく説明してもらえますか。","why":"elaborate on something。","level":"B2","unit":"b2-06"},{"id":"b2-06-q02","stem":"I take your ___, but I see it differently.","correct":"point","options":["point","opinion of","mind","idea to"],"jp":"言いたいことは分かるが見方が違う。","why":"I take your point は相手の論点を認める。","level":"B2","unit":"b2-06"},{"id":"b2-06-q03","stem":"That may be true; ___, we need more evidence.","correct":"nonetheless","options":["nonetheless","besides of","although","thereby of"],"jp":"それは正しいかもしれない。それでも追加の証拠が必要。","why":"独立した文をつなぐ nonetheless。","level":"B2","unit":"b2-06"},{"id":"b2-06-q04","stem":"I agree with the proposal in ___, but not with every detail.","correct":"principle","options":["principle","principal","practice of","principality"],"jp":"原則として賛成だが細部は違う。","why":"in principle は原則的に。","level":"B2","unit":"b2-06"},{"id":"b2-06-q05","stem":"Could we ___ back to the main question?","correct":"get","options":["get","go back to","returning","coming"],"jp":"本題に戻れますか。","why":"get back to the main question が自然。","level":"B2","unit":"b2-06"},{"id":"b2-06-q06","stem":"I think we're talking at cross ___.","correct":"purposes","options":["purposes","roads","meanings","points"],"jp":"議論がすれ違っていると思う。","why":"at cross purposes は互いに違う話をしている状況。","level":"B2","unit":"b2-06"},{"id":"b2-06-q07","stem":"Let's try to find some common ___.","correct":"ground","options":["ground","earth","flooring","basis of"],"jp":"共通の立場を探そう。","why":"find common ground は合意点を探す。","level":"B2","unit":"b2-06"},{"id":"b2-06-q08","stem":"We may have to ___ to disagree.","correct":"agree","options":["agree","acceptance","consent","permit"],"jp":"意見が一致しないことを認める必要があるかも。","why":"agree to disagree は見解の相違を受け入れる。","level":"B2","unit":"b2-06"}]},{"id":"c1-01","level":"C1","tag":"Inversion","title":"Inversion and emphasis","goal":"高度な倒置・強調を正しく扱う","rule":"否定副詞の前置による倒置と強調構文。","examples":["Rarely have I seen such a result. = このような結果は滅多に見ない。","Not until later did I understand. = 後になって初めて理解した。"],"questions":[{"id":"c1-01-q01","stem":"Rarely ___ such a persuasive argument.","correct":"have I heard","options":["have I heard","I have heard","I heard have","heard I have"],"jp":"これほど説得力のある議論は滅多に聞かない。","why":"文頭 Rarely で助動詞と主語が倒置。","level":"C1","unit":"c1-01"},{"id":"c1-01-q02","stem":"Not until the end ___ the full implications.","correct":"did we understand","options":["did we understand","we understood","had understood we","we did understand"],"jp":"最後になって初めて意味を理解した。","why":"Not until を文頭に置くと主節が倒置。","level":"C1","unit":"c1-01"},{"id":"c1-01-q03","stem":"Under no circumstances ___ confidential information.","correct":"should you disclose","options":["should you disclose","you should disclose","you disclose should","disclose you should"],"jp":"どんな場合も機密情報を公開してはならない。","why":"Under no circumstances による倒置。","level":"C1","unit":"c1-01"},{"id":"c1-01-q04","stem":"Hardly ___ the meeting started when the system failed.","correct":"had","options":["had","has","did","was"],"jp":"会議が始まるや否やシステムが落ちた。","why":"Hardly had ... when ...。","level":"C1","unit":"c1-01"},{"id":"c1-01-q05","stem":"Only after reviewing the data ___ the mistake.","correct":"did she notice","options":["did she notice","she noticed","has she notice","noticed she"],"jp":"データを見直して初めて彼女は誤りに気づいた。","why":"Only after で主節が倒置。","level":"C1","unit":"c1-01"},{"id":"c1-01-q06","stem":"Not only ___ the problem, but she also proposed a solution.","correct":"did she identify","options":["did she identify","she identified","does she identified","she did identified"],"jp":"問題を特定しただけでなく解決策も示した。","why":"文頭 Not only は倒置を要求する。","level":"C1","unit":"c1-01"},{"id":"c1-01-q07","stem":"So compelling ___ that the committee approved it unanimously.","correct":"was the evidence","options":["was the evidence","the evidence was","had evidence been","evidence was"],"jp":"証拠が強力だったため委員会は全会一致で承認した。","why":"So + 形容詞の前置で倒置。","level":"C1","unit":"c1-01"},{"id":"c1-01-q08","stem":"Little ___ how profoundly the decision would affect her.","correct":"did she realise","options":["did she realise","she realised","had realised she","realise she did"],"jp":"決断がどれほど影響するか、彼女はほぼ知らなかった。","why":"文頭 Little の否定的意味で倒置。","level":"C1","unit":"c1-01"}]},{"id":"c1-02","level":"C1","tag":"Nuance","title":"Epistemic nuance","goal":"確信度を精密に表す","rule":"hedging、推量、限定、慎重な主張。","examples":["This may well be the case. = 実際そうかもしれない。","It remains to be seen whether ... = …かはまだ分からない。"],"questions":[{"id":"c1-02-q01","stem":"The discrepancy may ___ be due to measurement error.","correct":"well","options":["well","good","highly","strong"],"jp":"その不一致は測定誤差が原因かもしれない。","why":"may well は「十分あり得る」。","level":"C1","unit":"c1-02"},{"id":"c1-02-q02","stem":"It remains to be ___ whether the intervention works.","correct":"seen","options":["seen","looked","watched","viewing"],"jp":"介入が効くかはまだ分からない。","why":"it remains to be seen whether が定型。","level":"C1","unit":"c1-02"},{"id":"c1-02-q03","stem":"The evidence is suggestive rather than ___.","correct":"conclusive","options":["conclusive","concluding","conclusively","conclusion"],"jp":"証拠は示唆的だが決定的ではない。","why":"conclusive evidence は決定的証拠。","level":"C1","unit":"c1-02"},{"id":"c1-02-q04","stem":"These findings should be interpreted with ___.","correct":"caution","options":["caution","cautiously","careless","warningly"],"jp":"この結果は慎重に解釈すべき。","why":"with caution が定型。","level":"C1","unit":"c1-02"},{"id":"c1-02-q05","stem":"The proposal is not without ___.","correct":"merit","options":["merit","merits to","meritorious","demerit only"],"jp":"提案にもそれなりの価値はある。","why":"not without merit は控えめな肯定。","level":"C1","unit":"c1-02"},{"id":"c1-02-q06","stem":"One could ___ that the sample is not representative.","correct":"argue","options":["argue","argument","argued","arguing"],"jp":"標本に代表性がないと論じることもできる。","why":"One could argue that ... は主張の慎重な提示。","level":"C1","unit":"c1-02"},{"id":"c1-02-q07","stem":"There is little ___ that the change was deliberate.","correct":"indication","options":["indication","indicate","indicative","indicating of"],"jp":"変更が意図的だったという兆候はほとんどない。","why":"little indication that ...。","level":"C1","unit":"c1-02"},{"id":"c1-02-q08","stem":"The pattern is broadly ___ with our hypothesis.","correct":"consistent","options":["consistent","consistency","consist","consistently"],"jp":"傾向は仮説とおおむね整合する。","why":"be consistent with。","level":"C1","unit":"c1-02"}]},{"id":"c1-03","level":"C1","tag":"Syntax","title":"Complex structures","goal":"長い英文の構造を正しく作る","rule":"分詞節、名詞化、形式主語、譲歩節。","examples":["Having reviewed the evidence, ... = 証拠を検討したうえで…。","What matters is whether ... = 重要なのは…かどうかだ。"],"questions":[{"id":"c1-03-q01","stem":"___ the evidence, the panel revised its decision.","correct":"Having reviewed","options":["Having reviewed","Have reviewed","Reviewed having","To having reviewed"],"jp":"証拠を検討したうえで委員会は決定を改めた。","why":"主節より先に完了した行為は Having + 過去分詞。","level":"C1","unit":"c1-03"},{"id":"c1-03-q02","stem":"What matters most ___ whether the approach is sustainable.","correct":"is","options":["is","are","be","being"],"jp":"何より重要なのは、その方法が持続可能かどうかだ。","why":"What matters most を一つの主語とみなす。","level":"C1","unit":"c1-03"},{"id":"c1-03-q03","stem":"The more thoroughly we test it, ___ confident we become.","correct":"the more","options":["the more","more","most","as more"],"jp":"試験を徹底するほど確信が強まる。","why":"the + 比較級, the + 比較級。","level":"C1","unit":"c1-03"},{"id":"c1-03-q04","stem":"Much as I ___ his work, I disagree with his conclusion.","correct":"admire","options":["admire","am admiring","admired to","admiration"],"jp":"彼の仕事を評価するものの結論には反対だ。","why":"Much as + 主語 + 動詞 は譲歩。","level":"C1","unit":"c1-03"},{"id":"c1-03-q05","stem":"___ it not been for her intervention, the project would have failed.","correct":"Had","options":["Had","If","Were","Should"],"jp":"彼女の介入がなければ企画は失敗していた。","why":"Had it not been for = If it had not been for。","level":"C1","unit":"c1-03"},{"id":"c1-03-q06","stem":"The proposal, ___ controversial, deserves serious consideration.","correct":"though","options":["though","despite","even","in spite"],"jp":"議論を呼ぶ提案だが真剣に検討する価値がある。","why":"省略譲歩節 though controversial。","level":"C1","unit":"c1-03"},{"id":"c1-03-q07","stem":"It is imperative that every applicant ___ informed.","correct":"be","options":["be","is","was","will be"],"jp":"すべての応募者への通知が不可欠だ。","why":"imperative that の後に原形 be を用いる正式用法。","level":"C1","unit":"c1-03"},{"id":"c1-03-q08","stem":"Were the funding to disappear, the programme ___ collapse.","correct":"would","options":["would","will","must have","is"],"jp":"資金がなくなれば企画は崩壊するだろう。","why":"Were + 主語 + to do の倒置仮定文には would。","level":"C1","unit":"c1-03"}]},{"id":"c1-04","level":"C1","tag":"Register","title":"Register and pragmatics","goal":"相手や場面に合わせて丁寧に伝える","rule":"フォーマルな依頼、婉曲表現、配慮ある修正。","examples":["I would appreciate it if ... = …していただけると幸いです。","With all due respect, ... = 敬意を払った上で申し上げると…。"],"questions":[{"id":"c1-04-q01","stem":"I would ___ it if you could clarify the deadline.","correct":"appreciate","options":["appreciate","be appreciated","appreciating","appreciation"],"jp":"締切を明確にしていただけると幸いです。","why":"I would appreciate it if が形式的かつ自然。","level":"C1","unit":"c1-04"},{"id":"c1-04-q02","stem":"With all due ___, I believe that assumption is flawed.","correct":"respect","options":["respect","respectful","respecting","respectfully"],"jp":"失礼を承知で申し上げますが、その前提には問題があると思います。","why":"With all due respect は意見の相違を丁寧に示す。","level":"C1","unit":"c1-04"},{"id":"c1-04-q03","stem":"I regret to ___ you that the application was unsuccessful.","correct":"inform","options":["inform","tell about","say on","informed"],"jp":"残念ながら応募は不採用でした。","why":"regret to inform はフォーマルな通知。","level":"C1","unit":"c1-04"},{"id":"c1-04-q04","stem":"I would be ___ if you could send the revised document.","correct":"grateful","options":["grateful","gratitude","gratified to","greatness"],"jp":"修正版を送っていただけるとありがたいです。","why":"would be grateful if ...。","level":"C1","unit":"c1-04"},{"id":"c1-04-q05","stem":"We may wish to ___ this matter at a later stage.","correct":"revisit","options":["revisit","visit again to","repeat again","revisiting"],"jp":"この問題を後で改めて検討した方がよいかもしれません。","why":"revisit a matter は再検討すること。","level":"C1","unit":"c1-04"},{"id":"c1-04-q06","stem":"Please do not ___ to contact me if you require assistance.","correct":"hesitate","options":["hesitate","pause","delay to","refuse"],"jp":"必要なら遠慮なく連絡してください。","why":"do not hesitate to ... は定型。","level":"C1","unit":"c1-04"},{"id":"c1-04-q07","stem":"I take ___ with the suggestion that the results are trivial.","correct":"issue","options":["issue","offence about","matter","problematic"],"jp":"結果が取るに足らないという提案には異議がある。","why":"take issue with は反論する。","level":"C1","unit":"c1-04"},{"id":"c1-04-q08","stem":"For the ___ of clarity, let me restate the conclusion.","correct":"sake","options":["sake","purpose to","reason of","side"],"jp":"明確にするため結論を言い直す。","why":"for the sake of clarity が慣用表現。","level":"C1","unit":"c1-04"}]},{"id":"c1-05","level":"C1","tag":"Analysis","title":"Advanced academic English","goal":"情報を統合・評価する","rule":"方法論・実証・限定・論証の語彙。","examples":["A plausible interpretation is ... = 妥当な解釈の一つは…。","The claim warrants scrutiny. = その主張は検証に値する。"],"questions":[{"id":"c1-05-q01","stem":"The claim warrants further ___.","correct":"scrutiny","options":["scrutiny","scrutinise","scrutinisingly","scrutinised"],"jp":"この主張はさらに検証する価値がある。","why":"warrant scrutiny は精査を要する。","level":"C1","unit":"c1-05"},{"id":"c1-05-q02","stem":"A plausible ___ is that expectations influenced responses.","correct":"interpretation","options":["interpretation","interpret","interpreted","interpretive of"],"jp":"妥当な解釈の一つは期待が回答に影響したというもの。","why":"plausible interpretation という名詞句。","level":"C1","unit":"c1-05"},{"id":"c1-05-q03","stem":"The results are ___ by several methodological limitations.","correct":"constrained","options":["constrained","constraint","constrainingly","restrictive of"],"jp":"結果は方法論的な制約を受けている。","why":"be constrained by ...。","level":"C1","unit":"c1-05"},{"id":"c1-05-q04","stem":"We should avoid ___ causal relationships from observational data alone.","correct":"inferring","options":["inferring","inference","to infer","inferred"],"jp":"観察データのみから因果関係を推測すべきでない。","why":"avoid + 動名詞。","level":"C1","unit":"c1-05"},{"id":"c1-05-q05","stem":"The argument rests on a ___ premise.","correct":"questionable","options":["questionable","questionably","questioned to","questioning of"],"jp":"議論は疑わしい前提に立っている。","why":"questionable は前提の確からしさに疑問を呈する。","level":"C1","unit":"c1-05"},{"id":"c1-05-q06","stem":"The findings appear robust ___ alternative specifications.","correct":"across","options":["across","toward","beside","onto"],"jp":"結果は別の仕様でも頑健そうだ。","why":"robust across ... は条件を変えても安定という意味。","level":"C1","unit":"c1-05"},{"id":"c1-05-q07","stem":"The study fails to account ___ an important confounding variable.","correct":"for","options":["for","with","to","by"],"jp":"研究は重要な交絡変数を考慮していない。","why":"account for a variable で考慮・説明する。","level":"C1","unit":"c1-05"},{"id":"c1-05-q08","stem":"It would be premature to draw a ___ conclusion.","correct":"definitive","options":["definitive","definitely","definition","definingly"],"jp":"決定的結論を出すには早い。","why":"draw a definitive conclusion。","level":"C1","unit":"c1-05"}]},{"id":"c1-06","level":"C1","tag":"Idiomatic","title":"Idiomatic precision","goal":"高度な慣用表現を適切に使う","rule":"英語的な比喩・定型句を文脈に合わせる。","examples":["a double-edged sword = 諸刃の剣。","the tip of the iceberg = 氷山の一角。"],"questions":[{"id":"c1-06-q01","stem":"Technology can be a double-edged ___.","correct":"sword","options":["sword","knife","blade edge","tooling"],"jp":"技術には良い面と悪い面がある。","why":"a double-edged sword は諸刃の剣。","level":"C1","unit":"c1-06"},{"id":"c1-06-q02","stem":"These complaints may be just the tip of the ___.","correct":"iceberg","options":["iceberg","mountain","glacier of","snowfall"],"jp":"苦情は問題の氷山の一角かもしれない。","why":"the tip of the iceberg は表面化した一部。","level":"C1","unit":"c1-06"},{"id":"c1-06-q03","stem":"We need to look at the bigger ___.","correct":"picture","options":["picture","photo","drawing","scenery"],"jp":"もっと大局を見る必要がある。","why":"look at the bigger picture は全体像を見る。","level":"C1","unit":"c1-06"},{"id":"c1-06-q04","stem":"The reform is a step in the right ___.","correct":"direction","options":["direction","pathway","movement","way of"],"jp":"改革は正しい方向への一歩だ。","why":"a step in the right direction が定型。","level":"C1","unit":"c1-06"},{"id":"c1-06-q05","stem":"The speaker managed to get her point ___.","correct":"across","options":["across","overhead","outward","onward"],"jp":"話者は自分の言いたいことを伝えられた。","why":"get one's point across は意図を伝える。","level":"C1","unit":"c1-06"},{"id":"c1-06-q06","stem":"He refused to take the proposal at face ___.","correct":"value","options":["value","level","rate","surface"],"jp":"彼は提案をそのまま信じなかった。","why":"take at face value は額面どおりに受け取る。","level":"C1","unit":"c1-06"},{"id":"c1-06-q07","stem":"It is important not to lose ___ of the original goal.","correct":"sight","options":["sight","viewing","visionary","seeing"],"jp":"当初の目標を見失わないことが重要。","why":"lose sight of は見失う。","level":"C1","unit":"c1-06"},{"id":"c1-06-q08","stem":"We're still a long ___ from finding a lasting solution.","correct":"way","options":["way","road","distance of","path to"],"jp":"永続的な解決策はまだ遠い。","why":"a long way from ... は距離の比喩。","level":"C1","unit":"c1-06"}]}],"readings":[{"id":"read-01","level":"A2","title":"A new routine","text":"Mia moved to a new town last month. She now walks to school because her house is only ten minutes away. At first, she felt lonely, but she joined a photography club. She has already made two friends there. Every Saturday, they take pictures of parks and old buildings.","questions":[{"id":"read-01-q1","stem":"Why does Mia walk to school?","correct":"Her school is close to home.","options":["Her school is close to home.","The buses are too expensive.","She dislikes cycling.","Her parents insist."],"jp":"ミアはなぜ歩いて通学する？","why":"徒歩10分と明記されている。","level":"A2","unit":"read-01","reading":"read-01"},{"id":"read-01-q2","stem":"How did Mia feel at first?","correct":"Lonely.","options":["Lonely.","Excited.","Angry.","Confident."],"jp":"最初はどう感じた？","why":"At first, she felt lonely。","level":"A2","unit":"read-01","reading":"read-01"},{"id":"read-01-q3","stem":"What club did she join?","correct":"A photography club.","options":["A photography club.","A chess club.","A swimming club.","A music club."],"jp":"どの部活に入った？","why":"photography club とある。","level":"A2","unit":"read-01","reading":"read-01"},{"id":"read-01-q4","stem":"What do they do on Saturdays?","correct":"Take photographs.","options":["Take photographs.","Play football.","Study languages.","Go shopping."],"jp":"土曜日に何をする？","why":"they take pictures と書かれている。","level":"A2","unit":"read-01","reading":"read-01"}]},{"id":"read-02","level":"A2","title":"A journey changed","text":"Ken planned to visit his cousin by train on Friday. However, heavy rain caused delays. The station staff advised him to take a bus instead. The bus took forty minutes longer than the train, but Ken arrived before dinner. His cousin had prepared his favourite meal.","questions":[{"id":"read-02-q1","stem":"What caused the delays?","correct":"Heavy rain.","options":["Heavy rain.","A strike.","An accident.","Snow."],"jp":"遅れの原因は？","why":"heavy rain caused delays。","level":"A2","unit":"read-02","reading":"read-02"},{"id":"read-02-q2","stem":"What alternative did the staff suggest?","correct":"A bus.","options":["A bus.","A taxi.","A bicycle.","A different flight."],"jp":"スタッフが勧めたのは？","why":"take a bus instead とある。","level":"A2","unit":"read-02","reading":"read-02"},{"id":"read-02-q3","stem":"How much longer did the bus take?","correct":"Forty minutes.","options":["Forty minutes.","Ten minutes.","An hour.","Two hours."],"jp":"バスはどれだけ余計にかかった？","why":"forty minutes longer。","level":"A2","unit":"read-02","reading":"read-02"},{"id":"read-02-q4","stem":"When did Ken arrive?","correct":"Before dinner.","options":["Before dinner.","After midnight.","At lunchtime.","The following day."],"jp":"ケンはいつ着いた？","why":"arrived before dinner。","level":"A2","unit":"read-02","reading":"read-02"}]},{"id":"read-03","level":"B1","title":"A student initiative","text":"A group of students noticed that many reusable water bottles were being thrown away. They organised a repair workshop and asked a local company to donate spare parts. The first event attracted only twelve participants, but the second drew more than fifty. The students now hope to make the workshop a monthly event.","questions":[{"id":"read-03-q1","stem":"What problem motivated the students?","correct":"Reusable bottles were being discarded.","options":["Reusable bottles were being discarded.","School lunches were costly.","People disliked sports.","Classrooms were overcrowded."],"jp":"発案のきっかけは？","why":"reusable bottles being thrown away。","level":"B1","unit":"read-03","reading":"read-03"},{"id":"read-03-q2","stem":"How did the local company help?","correct":"It donated spare parts.","options":["It donated spare parts.","It rented a building.","It printed advertisements.","It provided free transport."],"jp":"企業の協力内容は？","why":"donate spare parts とある。","level":"B1","unit":"read-03","reading":"read-03"},{"id":"read-03-q3","stem":"How did participation change?","correct":"It increased significantly.","options":["It increased significantly.","It stayed at twelve.","It decreased by half.","It became compulsory."],"jp":"参加者はどう変化した？","why":"12人から50人以上に増加。","level":"B1","unit":"read-03","reading":"read-03"},{"id":"read-03-q4","stem":"What is their next goal?","correct":"To run it every month.","options":["To run it every month.","To sell new bottles.","To cancel future events.","To open a restaurant."],"jp":"今後の目標は？","why":"make the workshop a monthly event。","level":"B1","unit":"read-03","reading":"read-03"}]},{"id":"read-04","level":"B1","title":"Working remotely","text":"When Lena began working from home, she expected to save time and feel less stressed. She did save money on transport, but found it harder to stop working in the evening. After a few months, she started closing her laptop at six and taking a short walk. She now believes that clear boundaries matter more than the location of one's desk.","questions":[{"id":"read-04-q1","stem":"Which benefit did Lena experience?","correct":"Lower transport costs.","options":["Lower transport costs.","A shorter working day.","A higher salary.","More holidays."],"jp":"どんな利点があった？","why":"saved money on transport。","level":"B1","unit":"read-04","reading":"read-04"},{"id":"read-04-q2","stem":"What was initially difficult?","correct":"Stopping work in the evening.","options":["Stopping work in the evening.","Using her laptop.","Talking to colleagues.","Finding an apartment."],"jp":"最初の問題は？","why":"harder to stop working in the evening。","level":"B1","unit":"read-04","reading":"read-04"},{"id":"read-04-q3","stem":"What habit did she adopt?","correct":"Finishing at six and walking.","options":["Finishing at six and walking.","Working until midnight.","Avoiding exercise.","Changing companies."],"jp":"新しい習慣は？","why":"closing her laptop at six and taking a walk。","level":"B1","unit":"read-04","reading":"read-04"},{"id":"read-04-q4","stem":"What is the main message?","correct":"Setting boundaries is essential.","options":["Setting boundaries is essential.","Everyone must work at home.","Commuting is always bad.","Working longer improves focus."],"jp":"主張の中心は？","why":"clear boundaries matter more と結論づけている。","level":"B1","unit":"read-04","reading":"read-04"}]},{"id":"read-05","level":"B2","title":"Interpreting a survey","text":"A survey of 600 commuters found that 68 percent supported expanding cycle lanes. At first glance, the result appeared decisive. However, the respondents had been recruited through a cycling association's newsletter. As a result, supporters of cycling may have been overrepresented. The researchers therefore advised against treating the figure as representative of all residents.","questions":[{"id":"read-05-q1","stem":"Why might the sample be biased?","correct":"It was recruited via a cycling newsletter.","options":["It was recruited via a cycling newsletter.","Too many people answered.","The survey was anonymous.","The percentage was rounded."],"jp":"なぜ標本が偏り得る？","why":"サイクリング団体の読者が中心。","level":"B2","unit":"read-05","reading":"read-05"},{"id":"read-05-q2","stem":"What does 68 percent refer to?","correct":"Survey respondents favouring cycle lanes.","options":["Survey respondents favouring cycle lanes.","All local residents who cycle.","Cyclists using buses.","Residents opposed to road changes."],"jp":"68%は何を表す？","why":"調査回答者の賛成割合。","level":"B2","unit":"read-05","reading":"read-05"},{"id":"read-05-q3","stem":"What did researchers warn against?","correct":"Generalising to all residents.","options":["Generalising to all residents.","Expanding the sample.","Collecting more data.","Publishing survey methods."],"jp":"研究者が注意した点は？","why":"全住民への一般化を避ける。","level":"B2","unit":"read-05","reading":"read-05"},{"id":"read-05-q4","stem":"What broader concept does this illustrate?","correct":"Selection bias.","options":["Selection bias.","Random assignment.","Double blinding.","Causal identification."],"jp":"これは何の例？","why":"特定の関心層が回答しやすい選択バイアス。","level":"B2","unit":"read-05","reading":"read-05"}]},{"id":"read-06","level":"B2","title":"Remote learning evidence","text":"An online learning platform reported that learners who watched more videos earned higher test scores. The company suggested that encouraging longer viewing would improve results. Yet the analysis did not control for prior knowledge or motivation. More engaged learners might both watch more and study more effectively. The correlation alone cannot establish the company's proposed causal mechanism.","questions":[{"id":"read-06-q1","stem":"What relationship did the company observe?","correct":"More viewing was associated with higher scores.","options":["More viewing was associated with higher scores.","Watching videos reduced scores.","Everyone watched equally.","Motivation had no effect."],"jp":"企業が観察した関係は？","why":"視聴時間と得点の相関。","level":"B2","unit":"read-06","reading":"read-06"},{"id":"read-06-q2","stem":"What important variables were not controlled?","correct":"Prior knowledge and motivation.","options":["Prior knowledge and motivation.","Internet speed alone.","Age and height.","Video resolution."],"jp":"統制されていなかった要因は？","why":"prior knowledge or motivation。","level":"B2","unit":"read-06","reading":"read-06"},{"id":"read-06-q3","stem":"What alternative explanation is offered?","correct":"Engaged learners may both watch more and study better.","options":["Engaged learners may both watch more and study better.","The videos were unavailable.","Tests were randomly assigned.","Everyone had identical skills."],"jp":"代替説明は？","why":"意欲が視聴と成績の両方を高める可能性。","level":"B2","unit":"read-06","reading":"read-06"},{"id":"read-06-q4","stem":"What cannot be concluded from the data alone?","correct":"That more viewing causes higher scores.","options":["That more viewing causes higher scores.","That participants watched videos.","That test scores varied.","That a correlation was observed."],"jp":"データだけでは何が言えない？","why":"因果関係は証明できない。","level":"B2","unit":"read-06","reading":"read-06"}]},{"id":"read-07","level":"C1","title":"A nuanced policy choice","text":"A city's pilot programme replaced parking spaces with small public gardens. Local shop owners initially predicted a decline in sales, whereas residents anticipated a more pleasant environment. After six months, pedestrian numbers had increased, but retail revenue had remained broadly stable. Because no comparable neighbourhood had been monitored, the researchers resisted attributing the changes solely to the gardens. Their report recommended extending the pilot while collecting better comparative data.","questions":[{"id":"read-07-q1","stem":"Why did researchers avoid a causal claim?","correct":"There was no comparable control neighbourhood.","options":["There was no comparable control neighbourhood.","Pedestrian numbers decreased.","Retail revenue collapsed.","Residents rejected the gardens."],"jp":"なぜ因果関係を断言しなかった？","why":"比較対象地区がなかった。","level":"C1","unit":"read-07","reading":"read-07"},{"id":"read-07-q2","stem":"Which observation challenges the shop owners' prediction?","correct":"Retail revenue remained broadly stable.","options":["Retail revenue remained broadly stable.","Gardens were removed immediately.","Parking spaces increased.","All businesses relocated."],"jp":"店主の予測に反する結果は？","why":"売上は概ね安定していた。","level":"C1","unit":"read-07","reading":"read-07"},{"id":"read-07-q3","stem":"What recommendation best reflects the report?","correct":"Continue cautiously with stronger evaluation.","options":["Continue cautiously with stronger evaluation.","End all experiments immediately.","Claim the gardens caused all changes.","Ignore business concerns entirely."],"jp":"報告の推奨は？","why":"比較データを集めながら継続。","level":"C1","unit":"read-07","reading":"read-07"},{"id":"read-07-q4","stem":"What is the author's epistemic stance?","correct":"Cautiously evidence-based.","options":["Cautiously evidence-based.","Completely certain.","Emotionally dismissive.","Entirely speculative."],"jp":"文章の認識態度は？","why":"結果は認めつつ因果を慎重に判断。","level":"C1","unit":"read-07","reading":"read-07"}]},{"id":"read-08","level":"C1","title":"Automation and judgement","text":"An organisation introduced an automated tool to shortlist job applicants. Efficiency improved, yet auditors later found that applicants with unconventional career paths were disproportionately excluded. The company defended the tool by citing its consistency, but critics noted that consistent application of a flawed criterion does not guarantee fairness. The subsequent review proposed transparent eligibility rules, regular audits and meaningful opportunities for human appeal.","questions":[{"id":"read-08-q1","stem":"What was the tool's initial advantage?","correct":"Greater efficiency.","options":["Greater efficiency.","More diverse candidates.","Fewer rules.","Perfect fairness."],"jp":"初期の利点は？","why":"Efficiency improved。","level":"C1","unit":"read-08","reading":"read-08"},{"id":"read-08-q2","stem":"Which group was disproportionately affected?","correct":"Applicants with unconventional careers.","options":["Applicants with unconventional careers.","Only internal staff.","Applicants with identical qualifications.","All managers."],"jp":"不利になった応募者は？","why":"unconventional career paths の人々。","level":"C1","unit":"read-08","reading":"read-08"},{"id":"read-08-q3","stem":"What is the critics' central argument?","correct":"Consistency does not by itself ensure fairness.","options":["Consistency does not by itself ensure fairness.","Automation always produces fairness.","Audits are unnecessary.","Human review is impossible."],"jp":"批判者の中心論点は？","why":"誤った基準を一貫して使っても公正とは限らない。","level":"C1","unit":"read-08","reading":"read-08"},{"id":"read-08-q4","stem":"Which safeguard was proposed?","correct":"Transparent criteria and human appeal.","options":["Transparent criteria and human appeal.","Removing all transparency.","Banning job applications.","Using fewer reviews."],"jp":"提案された対策は？","why":"透明な基準、監査、人による異議申立て。","level":"C1","unit":"read-08","reading":"read-08"}]}],"speaking":[{"id":"sp-01","level":"A2","prompt":"Introduce yourself in three sentences.","jp":"名前・住んでいる場所・好きなことを3文で紹介。","model":"I live near Geneva. I enjoy learning languages. In my free time, I play tennis.","tip":"現在形とつながりを意識する。"},{"id":"sp-02","level":"A2","prompt":"Describe what you did yesterday.","jp":"昨日の行動を順番に説明。","model":"Yesterday I went to school, finished my homework and watched a documentary.","tip":"過去形をそろえる。"},{"id":"sp-03","level":"A2","prompt":"Invite a friend to a museum.","jp":"友達を博物館に誘う。","model":"Would you like to visit the science museum with me on Saturday?","tip":"丁寧な誘いと日時。"},{"id":"sp-04","level":"A2","prompt":"Ask for directions at a station.","jp":"駅で道順を尋ねる。","model":"Excuse me, could you tell me how to get to the city centre?","tip":"Could you ... ? を使う。"},{"id":"sp-05","level":"A2","prompt":"Compare two cities you know.","jp":"知っている2都市を比較。","model":"Tokyo is bigger than Geneva, but Geneva is quieter.","tip":"比較級と but。"},{"id":"sp-06","level":"A2","prompt":"Explain your daily routine.","jp":"普段の一日を説明。","model":"I usually get up at seven and review English before school.","tip":"頻度の副詞を含める。"},{"id":"sp-07","level":"A2","prompt":"Talk about your plan for next weekend.","jp":"次の週末の予定。","model":"I'm going to meet a friend and work on a small project.","tip":"be going to を使う。"},{"id":"sp-08","level":"A2","prompt":"Politely ask someone to repeat something.","jp":"聞き返しを丁寧に行う。","model":"I'm sorry, could you say that again a little more slowly?","tip":"長くするより聞き取りやすく。"},{"id":"sp-09","level":"B1","prompt":"Describe an experience that changed your thinking.","jp":"考え方が変わった経験を述べる。","model":"When I joined a new class, I realised that listening matters more than speaking first.","tip":"経緯と学びを結ぶ。"},{"id":"sp-10","level":"B1","prompt":"Explain a personal goal and how you will reach it.","jp":"目標と達成方法を説明。","model":"I want to become more confident in English, so I practise speaking for ten minutes every day.","tip":"目的と手段をつなげる。"},{"id":"sp-11","level":"B1","prompt":"Give a balanced opinion about homework.","jp":"宿題の長所と短所を話す。","model":"Homework helps students review lessons. However, too much of it can reduce their free time.","tip":"譲歩と逆接。"},{"id":"sp-12","level":"B1","prompt":"Describe a problem and request a solution.","jp":"問題を説明して対応を依頼。","model":"I'm afraid there's a problem with my reservation. Could we change the date?","tip":"問題→希望の順。"},{"id":"sp-13","level":"B1","prompt":"Talk about a hypothetical change in your life.","jp":"もし〜ならどうするか話す。","model":"If I had more free time, I would learn another language.","tip":"If + 過去形、would。"},{"id":"sp-14","level":"B1","prompt":"Tell a story with a surprising ending.","jp":"意外な結末の短い話。","model":"I was waiting for the bus when I noticed that I'd left my bag at home.","tip":"過去進行・過去完了。"},{"id":"sp-15","level":"B1","prompt":"Explain why you prefer one learning method.","jp":"好みの学習方法を理由付きで説明。","model":"I prefer active practice because I remember expressions better when I use them.","tip":"理由を1つ以上。"},{"id":"sp-16","level":"B1","prompt":"Offer advice to a stressed classmate.","jp":"忙しい友達への助言。","model":"You could break the task into smaller steps and take short breaks.","tip":"should / could で押しつけを避ける。"},{"id":"sp-17","level":"B2","prompt":"Challenge a claim without sounding aggressive.","jp":"攻撃的にならず主張に異議。","model":"I see your point, but I think the evidence is insufficient to support that conclusion.","tip":"相手の意見→根拠の不足。"},{"id":"sp-18","level":"B2","prompt":"Explain correlation versus causation.","jp":"相関と因果の違いを説明。","model":"Two trends may occur together without one causing the other. A third factor could explain both.","tip":"third factor も言及。"},{"id":"sp-19","level":"B2","prompt":"Negotiate a compromise in a team.","jp":"チーム内で妥協点を探す。","model":"Could we combine both approaches? That would preserve the advantages of each.","tip":"代案を具体化。"},{"id":"sp-20","level":"B2","prompt":"Compare two policy options with trade-offs.","jp":"政策案の得失を比較。","model":"The first option is cheaper, whereas the second may produce better long-term outcomes.","tip":"比較＋不確実性。"},{"id":"sp-21","level":"B2","prompt":"Summarise an article and its limitations.","jp":"記事を要約し限界を述べる。","model":"The article argues that digital tools improve learning, although it provides little evidence about long-term effects.","tip":"主張と限界を区別。"},{"id":"sp-22","level":"B2","prompt":"Talk about how you manage complex tasks.","jp":"複雑なタスクの管理方法。","model":"I prioritise the most important tasks, set clear deadlines and review my progress weekly.","tip":"具体的な手順。"},{"id":"sp-23","level":"B2","prompt":"Explain a difficult decision you made.","jp":"難しい決断の理由を話す。","model":"I chose the slower option because it was more reliable, despite the extra effort required.","tip":"短期・長期の視点。"},{"id":"sp-24","level":"B2","prompt":"Respond to a counterargument constructively.","jp":"反論に建設的に返す。","model":"That's a fair concern. Nevertheless, I think we can reduce the risk with better safeguards.","tip":"反論を認めてから具体策。"},{"id":"sp-25","level":"C1","prompt":"Evaluate the reliability of an experiment.","jp":"実験の信頼性を検討。","model":"The results are suggestive, but the small sample and lack of a control group limit their generalisability.","tip":"断定の強さを調節。"},{"id":"sp-26","level":"C1","prompt":"Deliver a nuanced mini-presentation on AI and education.","jp":"AIと教育について短い発表。","model":"AI may enhance personalised learning, provided that we preserve independent thinking and transparent assessment.","tip":"条件とリスクを明示。"},{"id":"sp-27","level":"C1","prompt":"Explain the limits of a statistical claim.","jp":"統計的主張の限界を説明。","model":"While the association is statistically significant, it does not in itself establish a causal relationship.","tip":"significance と causality を区別。"},{"id":"sp-28","level":"C1","prompt":"Politely disagree in an academic discussion.","jp":"学術的議論で丁寧に異議。","model":"With respect, I would question whether the underlying assumption is adequately supported.","tip":"人ではなく前提を批判。"},{"id":"sp-29","level":"C1","prompt":"Outline a proposal with anticipated objections.","jp":"予想される反論を含め提案。","model":"I propose a limited pilot programme. Although implementation costs may be substantial, the potential benefits warrant evaluation.","tip":"提案、懸念、評価方法。"},{"id":"sp-30","level":"C1","prompt":"Analyse a social trend without overgeneralising.","jp":"社会現象を過度に一般化せず分析。","model":"The trend appears widespread, yet demographic differences and selection effects complicate interpretation.","tip":"限定・例外を含める。"},{"id":"sp-31","level":"C1","prompt":"Summarise contrasting perspectives fairly.","jp":"対立する見方を公平に要約。","model":"Proponents emphasise efficiency, whereas critics question accountability. Both concerns deserve serious attention.","tip":"両論を公正に。"},{"id":"sp-32","level":"C1","prompt":"Conclude a structured argument persuasively.","jp":"構造的な議論を締める。","model":"On balance, the evidence favours gradual implementation accompanied by independent evaluation.","tip":"結論を条件付きで述べる。"}],"writing":[{"id":"wr-01","level":"A2","prompt":"Write 4 sentences about your school day.","jp":"学校生活について4文。","starter":"I usually ...","criteria":"現在形・時刻・接続詞を含める"},{"id":"wr-02","level":"A2","prompt":"Write a short invitation.","jp":"友人への招待文を書く。","starter":"Would you like to ...?","criteria":"日時・場所・理由を明記"},{"id":"wr-03","level":"A2","prompt":"Describe a recent weekend.","jp":"最近の週末を説明。","starter":"Last weekend, I ...","criteria":"過去形を統一する"},{"id":"wr-04","level":"A2","prompt":"Compare two places.","jp":"2つの場所を比較。","starter":"... is ... than ...","criteria":"比較級を2種類以上使う"},{"id":"wr-05","level":"B1","prompt":"Write a short balanced opinion (80 words).","jp":"約80語の意見文。","starter":"In my view, ...","criteria":"意見・根拠・反論・結論"},{"id":"wr-06","level":"B1","prompt":"Write a polite complaint email.","jp":"丁寧な苦情メール。","starter":"I am writing about ...","criteria":"事情・問題点・希望する解決"},{"id":"wr-07","level":"B1","prompt":"Describe an important lesson learned.","jp":"経験から学んだこと。","starter":"I used to think ..., but ...","criteria":"変化の前後と具体例"},{"id":"wr-08","level":"B1","prompt":"Explain an ideal study plan.","jp":"理想的な勉強計画。","starter":"My main priority is ...","criteria":"目標・手順・見直し"},{"id":"wr-09","level":"B2","prompt":"Evaluate an argument (120 words).","jp":"約120語で主張を評価。","starter":"The argument assumes that ...","criteria":"前提・根拠・別解釈・限界"},{"id":"wr-10","level":"B2","prompt":"Write a proposal to your school.","jp":"学校向け提案書。","starter":"I propose introducing ...","criteria":"利点とコスト・実行方法"},{"id":"wr-11","level":"B2","prompt":"Compare the benefits and risks of AI.","jp":"AIの利益とリスクを比較。","starter":"Although AI can ..., it may also ...","criteria":"譲歩・具体例・条件"},{"id":"wr-12","level":"B2","prompt":"Summarise a news article without bias.","jp":"中立的にニュースを要約。","starter":"The article reports that ...","criteria":"事実と論評を分離"},{"id":"wr-13","level":"C1","prompt":"Write a nuanced essay introduction (150 words).","jp":"150語程度の論説導入。","starter":"The question of whether ...","criteria":"論点・対立軸・限定した主張"},{"id":"wr-14","level":"C1","prompt":"Critique a flawed experimental design.","jp":"実験設計の問題を批判的に検討。","starter":"A central methodological concern is ...","criteria":"標本・交絡・因果推論・改善策"},{"id":"wr-15","level":"C1","prompt":"Draft a formal response to a proposal.","jp":"提案への丁寧な正式回答。","starter":"Thank you for outlining ...","criteria":"評価・懸念・具体的な再提案"},{"id":"wr-16","level":"C1","prompt":"Write an executive summary on an education policy.","jp":"教育政策の要約を書く。","starter":"This proposal seeks to ...","criteria":"目的・根拠・トレードオフ・勧告"}]};
